package com.smartinternship.model; import jakarta.persistence.*; import java.time.LocalDate; @Entity @Table(name="applications") public class Application { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long studentId; private Long offerId; private String status; private LocalDate appliedAt; public Application(){} public Application(Long s,Long o){studentId=s;offerId=o;status="PENDING";appliedAt=LocalDate.now();} public Long getId(){return id;} public Long getStudentId(){return studentId;} public Long getOfferId(){return offerId;} public String getStatus(){return status;} public LocalDate getAppliedAt(){return appliedAt;} public void setId(Long x){id=x;} public void setStudentId(Long x){studentId=x;} public void setOfferId(Long x){offerId=x;} public void setStatus(String x){status=x;} public void setAppliedAt(LocalDate x){appliedAt=x;} }